package cn.lvxu.travel;
import org.json.*;import java.math.BigDecimal;import java.time.*;import java.util.*;
/** Local model. Money is cents, dates are ISO-8601, media paths are relative. */
public final class Trip {
 public String id=uid(),title="",city="",start=LocalDate.now().toString();public int importedLinkFallbacks;public int days=1;public long budget;public boolean pinned,archived,favorite;public long updatedAt=System.currentTimeMillis();
 public String departure="",companions="",vehicleNumber="",accommodation="",accommodationAddress="",accommodationSourceUrl="",accommodationSnapshot="",transportMode="步行";
 public final ArrayList<Stop> stops=new ArrayList<>();public final ArrayList<Expense> expenses=new ArrayList<>();public final ArrayList<Item> items=new ArrayList<>();public final ArrayList<Category> categories=new ArrayList<>();public final ArrayList<Checklist> lists=new ArrayList<>();public final ArrayList<Checkin> checkins=new ArrayList<>();
 public static String uid(){return UUID.randomUUID().toString();} public static long cents(String s){try{return amount(new BigDecimal(s.trim()).movePointRight(2).longValueExact());}catch(Exception e){throw new IllegalArgumentException("金额须为 0–100,000,000，最多两位小数");}} public static String money(long n){return BigDecimal.valueOf(n,2).stripTrailingZeros().toPlainString();}
 public long spent(){long n=0;for(Expense e:expenses)n+=e.amount;return n;}public long planned(){long n=0;for(Stop s:stops)n+=s.cost;return n;}public ArrayList<Stop> onDay(int d){ArrayList<Stop> x=new ArrayList<>();for(Stop s:stops)if(s.day==d)x.add(s);x.sort(Comparator.comparingInt((Stop s)->s.sortOrder<0?Integer.MAX_VALUE:s.sortOrder).thenComparing(s->s.time));return x;}public Category category(String id){for(Category c:categories)if(c.id.equals(id))return c;return null;}public Checklist list(String id){for(Checklist l:lists)if(l.id.equals(id))return l;return null;}
 public void reorderDay(int day,List<String> ids){ArrayList<Stop> current=onDay(day);if(current.size()!=ids.size())throw new IllegalArgumentException("地点列表已变化，请重试");HashMap<String,Stop> byId=new HashMap<>();for(Stop s:current)byId.put(s.id,s);HashSet<String> seen=new HashSet<>();for(String id:ids)if(!byId.containsKey(id)||!seen.add(id))throw new IllegalArgumentException("地点顺序无效");for(int i=0;i<ids.size();i++)byId.get(ids.get(i)).sortOrder=i;}
 public void normalize(){if(lists.isEmpty())lists.add(new Checklist("出发清单"));if(categories.isEmpty()){String[] n={"餐饮","交通","住宿","门票","购物","其他"};int[] c={0xffE07A5F,0xff3D85C6,0xff8064A2,0xffD6A84B,0xff4F9D69,0xff829399};for(int i=0;i<n.length;i++)categories.add(new Category(n[i],c[i]));}HashSet<String> li=new HashSet<>(),ci=new HashSet<>();for(Checklist l:lists)if(empty(l.id)||!li.add(l.id))l.id=uid();for(Category c:categories)if(empty(c.id)||!ci.add(c.id))c.id=uid();for(Item i:items){if(empty(i.id))i.id=uid();if(empty(i.listId)||list(i.listId)==null)i.listId=lists.get(0).id;if(i.importance==null)i.importance="普通";}for(Expense e:expenses){if(empty(e.id))e.id=uid();Category c=category(e.categoryId);if(c==null){for(Category x:categories)if(x.name.equals(e.category)){c=x;break;}if(c==null)c=categories.get(categories.size()-1);e.categoryId=c.id;}e.category=c.name;if(empty(e.occurredAt))e.occurredAt=LocalDateTime.now().withSecond(0).withNano(0).toString();}for(Stop s:stops){if(empty(s.id))s.id=uid();if(empty(s.coordinateSystem))s.coordinateSystem="WGS84";}for(Checkin c:checkins){if(empty(c.id))c.id=uid();if(empty(c.coordinateSystem))c.coordinateSystem="WGS84";}}
 public void deleteCategory(String oldId,String replacementId){Category old=category(oldId),r=category(replacementId);if(old==null||r==null||old==r)throw new IllegalArgumentException("请选择其他分类接收原账单");for(Expense e:expenses)if(oldId.equals(e.categoryId)){e.categoryId=r.id;e.category=r.name;}categories.remove(old);}
 public JSONObject json()throws JSONException{normalize();JSONObject o=new JSONObject().put("id",id).put("title",title).put("city",city).put("start",start).put("days",days).put("budget",budget).put("departure",departure).put("companions",companions).put("vehicleNumber",vehicleNumber).put("accommodation",accommodation).put("accommodationAddress",accommodationAddress).put("accommodationSourceUrl",accommodationSourceUrl).put("accommodationSnapshot",accommodationSnapshot).put("transportMode",transportMode);JSONArray a=new JSONArray();for(Stop v:stops)a.put(v.json());o.put("stops",a);a=new JSONArray();for(Expense v:expenses)a.put(v.json());o.put("expenses",a);a=new JSONArray();for(Item v:items)a.put(v.json());o.put("items",a);a=new JSONArray();for(Category v:categories)a.put(v.json());o.put("categories",a);a=new JSONArray();for(Checklist v:lists)a.put(v.json());o.put("lists",a);a=new JSONArray();for(Checkin v:checkins)a.put(v.json());return o.put("checkins",a);}
 public static Trip from(JSONObject o)throws JSONException{Trip t=new Trip();t.id=str(o,"id",uid(),100);t.title=str(o,"title","",80);t.city=str(o,"city","",80);t.start=LocalDate.parse(str(o,"start",LocalDate.now().toString(),20)).toString();t.departure=str(o,"departure","",120);t.companions=str(o,"companions","",500);t.vehicleNumber=str(o,"vehicleNumber","",100);t.accommodation=str(o,"accommodation","",120);t.accommodationAddress=str(o,"accommodationAddress","",300);t.accommodationSourceUrl=str(o,"accommodationSourceUrl","",1000);t.accommodationSnapshot=str(o,"accommodationSnapshot","",6000);t.transportMode=str(o,"transportMode","步行",30);t.days=o.optInt("days",1);t.budget=amount(o.optLong("budget",0));if(t.days<1||t.days>60||empty(t.title)||empty(t.city))throw new IllegalArgumentException("行程无效");JSONArray a=o.optJSONArray("categories");if(a!=null){limit(a,100,"分类太多");for(int k=0;k<a.length();k++)t.categories.add(Category.from(a.getJSONObject(k)));}a=o.optJSONArray("lists");if(a!=null){limit(a,100,"清单太多");for(int k=0;k<a.length();k++)t.lists.add(Checklist.from(a.getJSONObject(k)));}a=o.optJSONArray("stops");if(a!=null){limit(a,1000,"地点太多");for(int k=0;k<a.length();k++){Stop s=Stop.from(a.getJSONObject(k));if(s.day<0||s.day>=t.days||s.duration<1||s.duration>1440)throw new IllegalArgumentException("日程无效");t.stops.add(s);}}a=o.optJSONArray("expenses");if(a!=null){limit(a,5000,"费用太多");for(int k=0;k<a.length();k++)t.expenses.add(Expense.from(a.getJSONObject(k)));}a=o.optJSONArray("items");if(a!=null){limit(a,5000,"清单太长");for(int k=0;k<a.length();k++)t.items.add(Item.from(a.getJSONObject(k)));}a=o.optJSONArray("checkins");if(a!=null){limit(a,5000,"打卡太多");for(int k=0;k<a.length();k++)t.checkins.add(Checkin.from(a.getJSONObject(k)));}t.normalize();return t;}
 static boolean empty(String s){return s==null||s.trim().isEmpty();}static String bounded(String s,int n){if(s==null)s="";if(s.length()>n)throw new IllegalArgumentException("文字过长");return s;}static String str(JSONObject o,String k,String d,int n){return bounded(o.optString(k,d),n);}static long amount(long n){if(n<0||n>10000000000L)throw new IllegalArgumentException("金额无效");return n;}static void limit(JSONArray a,int n,String m){if(a.length()>n)throw new IllegalArgumentException(m);}static Double nullable(JSONObject o,String k){if(!o.has(k)||o.isNull(k))return null;double d=o.optDouble(k,Double.NaN);if(!Double.isFinite(d))throw new IllegalArgumentException("坐标无效");return d;}static String media(String s){s=bounded(s,500).replace('\\','/');if(s.startsWith("/")||s.contains("../")||s.equals("..")||s.contains(":"))throw new IllegalArgumentException("媒体路径无效");return s;}static String coords(String s){s=bounded(s,20);if(!s.equals("WGS84")&&!s.equals("GCJ02")&&!s.equals("BD09"))throw new IllegalArgumentException("坐标系无效");return s;}static void pair(Double lat,Double lon){if((lat==null)!=(lon==null)||(lat!=null&&(lat<-90||lat>90||lon<-180||lon>180)))throw new IllegalArgumentException("坐标无效");}
 public static class Stop{public String id=uid(),name="",time="09:00",mode="步行",note="",address="",openingHours="",sourceUrl="",sourceSnapshot="",coordinateSystem="WGS84";public String previewPhoto="";public final ArrayList<String> notePhotos=new ArrayList<>();public int day,duration=60,sortOrder=-1;public long cost;public Double lat,lon;public Float rating;JSONObject json()throws JSONException{pair(lat,lon);JSONObject o=new JSONObject().put("id",id).put("name",name).put("time",time).put("day",day).put("duration",duration).put("sortOrder",sortOrder).put("mode",mode).put("note",note).put("cost",cost).put("address",address).put("openingHours",openingHours).put("sourceUrl",sourceUrl).put("sourceSnapshot",sourceSnapshot).put("previewPhoto",media(previewPhoto)).put("notePhotos",Checkin.mediaArray(notePhotos)).put("coordinateSystem",coords(coordinateSystem));if(lat!=null)o.put("lat",lat);if(lon!=null)o.put("lon",lon);if(rating!=null)o.put("rating",rating);return o;}static Stop from(JSONObject v)throws JSONException{Stop s=new Stop();s.id=str(v,"id",uid(),100);s.name=str(v,"name","",120);s.time=str(v,"time","09:00",5);LocalTime.parse(s.time);if(!s.time.matches("\\d{2}:\\d{2}"))throw new IllegalArgumentException("时间无效");s.day=v.optInt("day");s.sortOrder=v.optInt("sortOrder",-1);if(s.sortOrder< -1||s.sortOrder>1000)throw new IllegalArgumentException("地点顺序无效");s.duration=v.optInt("duration",60);s.mode=str(v,"mode","步行",30);s.note=str(v,"note","",2000);s.cost=amount(v.optLong("cost"));s.address=str(v,"address","",300);s.openingHours=str(v,"openingHours","",300);s.sourceUrl=str(v,"sourceUrl","",1000);s.sourceSnapshot=str(v,"sourceSnapshot","",6000);s.previewPhoto=media(str(v,"previewPhoto","",500));Checkin.readMedia(v.optJSONArray("notePhotos"),s.notePhotos);s.lat=nullable(v,"lat");s.lon=nullable(v,"lon");pair(s.lat,s.lon);s.coordinateSystem=coords(str(v,"coordinateSystem","WGS84",20));if(v.has("rating")&&!v.isNull("rating")){float r=(float)v.optDouble("rating");if(Float.isFinite(r)&&r>=0&&r<=5)s.rating=r;else throw new IllegalArgumentException("评分无效");}return s;}}
 public static class Expense{public String id=uid(),name="",category="餐饮",categoryId="",occurredAt="";public long amount;JSONObject json()throws JSONException{return new JSONObject().put("id",id).put("name",name).put("category",category).put("categoryId",categoryId).put("occurredAt",occurredAt).put("amount",amount);}static Expense from(JSONObject v){Expense e=new Expense();e.id=str(v,"id",uid(),100);e.name=str(v,"name","",120);e.category=str(v,"category","其他",30);e.categoryId=str(v,"categoryId","",100);e.amount=amount(v.optLong("amount"));e.occurredAt=str(v,"occurredAt","",40);if(!empty(e.occurredAt))LocalDateTime.parse(e.occurredAt);return e;}}
 public static class Item{public String id=uid(),name="",listId="",importance="普通",note="",photo="";public boolean done;public final LinkedHashMap<String,String> attributes=new LinkedHashMap<>();public Item(){}public Item(String n){name=n;}JSONObject json()throws JSONException{JSONObject a=new JSONObject();for(Map.Entry<String,String> e:attributes.entrySet())a.put(e.getKey(),e.getValue());return new JSONObject().put("id",id).put("name",name).put("done",done).put("listId",listId).put("importance",importance).put("note",note).put("photo",media(photo)).put("attributes",a);}static Item from(JSONObject v){Item i=new Item();i.id=str(v,"id",uid(),100);i.name=str(v,"name","",120);i.done=v.optBoolean("done");i.listId=str(v,"listId","",100);i.importance=str(v,"importance","普通",10);i.note=str(v,"note","",2000);i.photo=media(str(v,"photo","",500));JSONObject a=v.optJSONObject("attributes");if(a!=null){if(a.length()>30)throw new IllegalArgumentException("自定义字段太多");for(Iterator<String> it=a.keys();it.hasNext();){String k=it.next();i.attributes.put(bounded(k,40),bounded(a.optString(k),300));}}return i;}}
 public static class Category{public String id=uid(),name="";public int color=0xff829399;public Category(){}public Category(String n,int c){name=n;color=c;}JSONObject json()throws JSONException{return new JSONObject().put("id",id).put("name",name).put("color",color);}static Category from(JSONObject v){Category c=new Category();c.id=str(v,"id",uid(),100);c.name=str(v,"name","",30);c.color=v.optInt("color",0xff829399);if(empty(c.name))throw new IllegalArgumentException("分类名称无效");return c;}}
 public static class Checklist{public String id=uid(),name="";public Checklist(){}public Checklist(String n){name=n;}JSONObject json()throws JSONException{return new JSONObject().put("id",id).put("name",name);}static Checklist from(JSONObject v){Checklist l=new Checklist();l.id=str(v,"id",uid(),100);l.name=str(v,"name","",50);if(empty(l.name))throw new IllegalArgumentException("清单名称无效");return l;}}
 public static class Checkin{public String id=uid(),photo="",card="",place="",mood="",time="",coordinateSystem="WGS84";public final ArrayList<String> groupPhotos=new ArrayList<>(),sceneryPhotos=new ArrayList<>(),companions=new ArrayList<>();public Double lat,lon;public float accuracy;
  JSONObject json()throws JSONException{pair(lat,lon);JSONObject o=new JSONObject().put("id",id).put("photo",media(photo)).put("card",media(card)).put("place",place).put("mood",mood).put("time",time).put("coordinateSystem",coords(coordinateSystem)).put("accuracy",accuracy).put("groupPhotos",mediaArray(groupPhotos)).put("sceneryPhotos",mediaArray(sceneryPhotos)).put("companions",textArray(companions));if(lat!=null)o.put("lat",lat);if(lon!=null)o.put("lon",lon);return o;}
  static JSONArray mediaArray(List<String> values)throws JSONException{if(values.size()>50)throw new IllegalArgumentException("每类照片最多 50 张");JSONArray a=new JSONArray();for(String value:values)a.put(media(value));return a;}
  static JSONArray textArray(List<String> values)throws JSONException{if(values.size()>50)throw new IllegalArgumentException("同行人员最多 50 位");JSONArray a=new JSONArray();for(String value:values){String clean=bounded(value,40).trim();if(!empty(clean))a.put(clean);}return a;}
  static void readMedia(JSONArray source,ArrayList<String> target)throws JSONException{if(source==null)return;limit(source,50,"每类照片最多 50 张");for(int i=0;i<source.length();i++)target.add(media(bounded(source.getString(i),500)));}
  static void readPeople(JSONArray source,ArrayList<String> target)throws JSONException{if(source==null)return;limit(source,50,"同行人员最多 50 位");for(int i=0;i<source.length();i++){String person=bounded(source.getString(i),40).trim();if(!empty(person))target.add(person);}}
  static Checkin from(JSONObject v)throws JSONException{Checkin c=new Checkin();c.id=str(v,"id",uid(),100);c.photo=media(str(v,"photo","",500));c.card=media(str(v,"card","",500));c.place=str(v,"place","",120);c.mood=str(v,"mood","",500);c.time=str(v,"time","",40);if(!empty(c.time))LocalDateTime.parse(c.time);c.lat=nullable(v,"lat");c.lon=nullable(v,"lon");pair(c.lat,c.lon);c.coordinateSystem=coords(str(v,"coordinateSystem","WGS84",20));c.accuracy=(float)v.optDouble("accuracy",0);if(!Float.isFinite(c.accuracy)||c.accuracy<0)throw new IllegalArgumentException("定位精度无效");readMedia(v.optJSONArray("groupPhotos"),c.groupPhotos);readMedia(v.optJSONArray("sceneryPhotos"),c.sceneryPhotos);readPeople(v.optJSONArray("companions"),c.companions);if(c.groupPhotos.isEmpty()&&!empty(c.photo))c.groupPhotos.add(c.photo);return c;}}
 public static Trip demo(){Trip t=new Trip();t.title="杭州 · 把日子交给山水";t.city="杭州";t.start=LocalDate.now().plusDays(7).toString();t.days=3;t.budget=180000;t.normalize();String[] n={"西湖 · 断桥残雪","北山街","曲院风荷","灵隐寺","法喜寺","小河直街"},tm={"09:00","11:00","14:00","09:30","14:00","10:00"};double[] lat={30.2590,30.2631,30.2534,30.2403,30.1998,30.3122},lon={120.1487,120.1512,120.1357,120.1018,120.1032,120.1372};for(int k=0;k<n.length;k++){Stop s=new Stop();s.name=n[k];s.time=tm[k];s.lat=lat[k];s.lon=lon[k];s.day=k<3?0:k<5?1:2;s.duration=90;s.mode=k==0?"地铁":"步行";s.note=k==0?"示例安排：沿湖慢走，给拍照留一点时间。":"示例地点，请自行确认开放时间与交通。";s.cost=k==3?7500:0;t.stops.add(s);}t.items.add(new Item("身份证 / 护照"));t.items.add(new Item("充电器与充电宝"));t.items.add(new Item("确认住宿与车票"));t.normalize();return t;}
}
